import{LAB_TOKENS,LAB_CHOICES,labKey,labTruth,labHypotheses,newLab,labStep,restoreLab,runRecipe,labCertificate}from'./rule-lab.js';
const labRoot=document.querySelector('#app');
const lEsc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lRead=k=>{try{return JSON.parse(window.fixiverseStorage.getItem(k)||'null');}catch{return null;}};
const lKey=m=>`fixiverse-rule-lab-${m}-v1`;
const lNames={left:'the left piece',equal:'same-sized pieces',right:'the right piece',sun:'sun',leaf:'leaf',star:'star',moon:'moon'};
const lIcons={sun:'☀',leaf:'❧',star:'★',moon:'☾'};
let labState=null,labError='',labTrace=0,traceVisible=false;
const lButton=(label,action,attrs='',secondary=false)=>`<button class="btn ${secondary?'secondary':''}" data-lab="${action}" ${attrs}>${label}</button>`;
const tile=(token,outline=false)=>`<span class="grove-tile ${token} ${outline?'loop-tile':''}" role="img" aria-label="${token}">${lIcons[token]}</span>`;
const taskName=t=>t.kind==='fraction'?`1/${t.pair[0]} and 1/${t.pair[1]}`:`${t.block.join(' / ')} · ${t.length} shown`;
function labVisual(t){if(t.kind==='fraction')return`<div class="lab-fraction-model">${t.pair.map((n,i)=>`<div class="growth-bar-line"><span class="fraction" aria-label="one over ${n}"><em>1</em><i>${n}</i></span><div><span class="growth-bar-label">${i?'RIGHT':'LEFT'} WHOLE · ONE SHADED PIECE</span><div class="fraction-bar" role="img" aria-label="${i?'Right':'Left'} same-sized whole in ${n} equal parts, one shaded">${Array.from({length:n},(_,j)=>`<i class="part ${j?'':'selected'}"></i>`).join('')}</div></div></div>`).join('')}<p class="hint-text">The wholes match. Every part in a whole is equal.</p></div>`;return`<div class="lab-loop-model"><span class="eyebrow">THE LITTLE LOOP</span><div class="lab-small-loop">${t.block.map(x=>tile(x,true)).join('')}</div><p>Follow the loop across, then down if the path wraps.</p><div class="pattern-path">${Array.from({length:t.length},(_,i)=>tile(t.block[i%t.block.length],i<t.block.length)).join('')}<span class="grove-tile mystery" role="img" aria-label="Missing next tile">?</span></div></div>`;}
function showLab(m='fraction'){if(!['fraction','pattern'].includes(m))m='fraction';history.replaceState(null,'',location.pathname+location.search+'#lab-'+m);labError='';traceVisible=false;const saved=lRead(lKey(m));try{labState=saved?restoreLab(saved,m):newLab(m);}catch{labState=newLab(m);labError='The saved lab could not be restored. A new draft is open; the old save is kept until you make a new change.';}renderLab();}
function storeLab(next){window.fixiverseStorage.setItem(lKey(next.mission),JSON.stringify(next));labState=next;}
function recipeControls(){const s=labState;if(s.mission==='fraction')return`<div class="recipe-blocks">${[['fewer','IF the left whole has fewer equal parts'],['equal','IF both wholes have the same number of parts'],['more','IF the left whole has more equal parts']].map(([slot,label],i)=>`<label class="recipe-block"><span class="recipe-step">0${i+1}</span><span>${label}<small>THEN</small></span><select data-lab-recipe="${slot}" aria-label="${label}, choose a piece">${LAB_CHOICES.map(v=>`<option value="${v}" ${s.recipe[slot]===v?'selected':''}>${v==='equal'?'Call the pieces the same':`Choose the ${v} piece`}</option>`).join('')}</select></label>`).join('')}</div>`;
return`<div class="recipe-blocks">${[['start','Start the pointer',[['first','At the first loop tile'],['last','At the last loop tile']]],['move','Move the pointer',[['shown','One step for each shown tile'],['none','Do not move it']]],['end','When you reach the end',[['wrap','Start at the first tile again'],['stay','Stay at the last tile']]]].map(([slot,label,opts],i)=>`<label class="recipe-block"><span class="recipe-step">0${i+1}</span><span>${label}</span><select data-lab-recipe="${slot}" aria-label="${label}">${opts.map(([v,text])=>`<option value="${v}" ${s.recipe[slot]===v?'selected':''}>${text}</option>`).join('')}</select></label>`).join('')}</div>`;}
function experimentPanel(){const s=labState,t=s.task,kept=s.evidence.some(e=>labKey(e.task)===labKey(t)),choices=s.mission==='fraction'?LAB_CHOICES:LAB_TOKENS;
return`<section class="panel lab-workbench"><div class="panel-head"><span class="panel-title">01 / Build a clue</span><span class="label">YOU CHOOSE THE EXPERIMENT</span></div><div class="panel-body"><h2>What would you like to try?</h2><div class="lab-case-controls">${s.mission==='fraction'?t.pair.map((n,i)=>`<label>${i?'Right':'Left'} whole<select data-lab-field="part-${i}" aria-label="${i?'Right':'Left'} equal parts">${Array.from({length:7},(_,j)=>`<option value="${j+2}" ${n===j+2?'selected':''}>${j+2} equal parts</option>`).join('')}</select></label>`).join(''):`<label>Little loop<select data-lab-field="loop-size" aria-label="Loop size"><option value="2" ${t.block.length===2?'selected':''}>2 different tiles</option><option value="3" ${t.block.length===3?'selected':''}>3 different tiles</option></select></label>${t.block.map((token,i)=>`<label>Tile ${i+1}<select data-lab-field="token-${i}" aria-label="Loop tile ${i+1}">${LAB_TOKENS.map(v=>`<option value="${v}" ${token===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label>Path length<select data-lab-field="length" aria-label="Shown path length">${Array.from({length:7},(_,i)=>`<option value="${i+2}" ${t.length===i+2?'selected':''}>${i+2} tiles</option>`).join('')}</select></label>`}</div>${labVisual(t)}<h3>${s.mission==='fraction'?'Which shaded piece is bigger?':'Which tile comes next?'}</h3><div class="lab-answer-choices" role="group" aria-label="Your prediction">${choices.map(v=>`<button class="choice ${s.choice===v?'selected':''}" data-lab="choose" data-value="${v}" aria-label="${s.mission==='fraction'?{left:'Left piece',equal:'Same size',right:'Right piece'}[v]:v}" aria-pressed="${s.choice===v}">${s.mission==='fraction'?{left:'Left piece',equal:'Same size',right:'Right piece'}[v]:`${tile(v)}<span>${v}</span>`}</button>`).join('')}</div><div class="btn-row">${lButton('Test my prediction','test',s.choice?'':'disabled')}${lButton('Help me find a useful test','suggest',s.alive.length<2?'disabled':'',true)}</div>${s.test?`<div class="result ${s.test.correct?'':'soft'}" role="status"><b>${s.test.correct?'Your prediction fits the model.':'A clue to look at together.'}</b><p>${s.test.correct?s.test.separates?'The remaining rules make different predictions here. This can become evidence.':'The remaining rules agree here. It does not tell them apart.':`The model points to ${lNames[labTruth(t)]}. Look at the pieces or follow the loop, then try your prediction again.`}</p>${s.test.correct&&s.test.separates&&!kept?lButton('Keep my clue →','keep'):''}</div>`:''}${kept?'<p class="lab-kept">✓ This clue is in your notebook.</p>':''}${s.evidence.length?`<div class="lab-next-step"><p>${s.alive.length===1?'Your clues leave one rule. Ready to make your own recipe?':'You have a useful clue. Try another case or build your recipe.'}</p>${lButton('Build my recipe →','recipe')}</div>`:''}</div></section>`;}
function ruleCards(){const s=labState;return`<section class="lab-hypotheses"><div class="section-heading"><h2>What could Pip be thinking?</h2><span>${s.alive.length} of 4 rules still fit your clues</span></div><p class="lab-small">A rule can match one example and fail another. Only your kept clues rule ideas out.</p><div class="hypothesis-grid">${labHypotheses(s.mission).map((h,i)=>`<article class="hypothesis-card ${s.alive.includes(h.id)?'alive':'ruled-out'}"><span class="hypothesis-number">${String.fromCharCode(65+i)}</span><h3>${h.name}</h3><span class="hypothesis-status">${s.alive.includes(h.id)?'Still fits your clues':'Ruled out by a clue'}</span>${s.test?`<p>This test predicts <b>${lNames[s.test.predictions.find(p=>p.id===h.id).prediction]}</b>.</p>`:'<p>Make your prediction to see what this rule chooses.</p>'}</article>`).join('')}</div></section>`;}
function notebook(){const s=labState;return`<aside class="lab-notebook"><div class="eyebrow">MY CLUE NOTEBOOK</div><h2>Little examples.<br> Real discoveries.</h2>${s.evidence.length?`<ol>${s.evidence.map(e=>`<li><b>${lEsc(taskName(e.task))}</b><span>My idea: ${lNames[e.choice]}.</span><small>Ruled out ${e.eliminated.length} ${e.eliminated.length===1?'rule':'rules'}.</small></li>`).join('')}</ol>`:'<p>Keep one correct prediction where at least two remaining rules disagree.</p><p>You can build your own experiment or ask for a suggestion.</p>'}<div class="lab-notebook-stats"><span><b>${s.evidence.length}</b> ${s.evidence.length===1?'clue':'clues'} kept</span><span><b>${s.hints}</b> ${s.hints===1?'suggestion':'suggestions'} used</span></div>${s.evidence.length?lButton('Make my own recipe →','recipe'):''}<p class="lab-small">Suggestions are recorded as support. Asking for help belongs here.</p></aside>`;}
function recipePanel(){const s=labState,last=s.runs.at(-1),trace=traceVisible&&last&&JSON.stringify(last.recipe)===JSON.stringify(s.recipe)?last.trace:null;
return`<section class="panel"><div class="panel-head"><span class="panel-title">02 / Make your own rule</span><span class="label">A RECIPE PIP CAN FOLLOW</span></div><div class="panel-body"><h2>Tell Pip what to do.</h2><p>Choose what Pip should do in each situation. Run the recipe to follow its steps. Then check every case in the collection.</p>${recipeControls()}<div class="btn-row">${lButton('Run my recipe','run','',true)}${lButton(`Check all ${s.mission==='fraction'?49:252} cases`,'verify')}</div>${trace?`<div class="lab-trace" role="status"><span class="eyebrow">PIP FOLLOWS YOUR RECIPE / ${taskName(s.task)}</span><ol>${trace.steps.map((step,i)=>`<li class="${labTrace===i?'trace-active':''}" ${labTrace===i?'aria-current="step"':''}><b>${step.label}</b><span>${step.value}</span></li>`).join('')}</ol><p>My recipe picks <b>${lNames[trace.prediction]}</b>.</p>${lButton('Follow the next instruction','trace-next','',true)}</div>`:''}${s.verified&&!s.verified.correct?`<div class="lab-counterexample result soft" role="status"><span class="eyebrow">A SMALL EXAMPLE THAT STILL NEEDS YOUR HELP</span><h3>${s.verified.passed} of ${s.verified.total} cases fit.</h3><p>On ${taskName(s.verified.counterexample.task)}, your recipe picks ${lNames[s.verified.counterexample.got]}. The model points to ${lNames[s.verified.counterexample.expected]}.</p>${labVisual(s.verified.counterexample.task)}${lButton('Investigate this example →','counterexample')}<p class="lab-small">A failing example is useful evidence about the recipe, not a grade for you.</p></div>`:''}<div class="lab-scope"><b>What is in this little collection?</b><p>${s.mission==='fraction'?'All 49 ordered pairs of part counts from 2 to 8. One piece from each of two matching wholes.':'All 252 loops of 2 or 3 distinct sun/leaf/star/moon tiles, with 2 to 8 shown tiles.'}</p><small>This checks only the stated collection. It does not establish mastery or a universal mathematical proof.</small></div><div class="btn-row">${lButton('Back to my experiments','experiment','',true)}</div></div></section>`;}
function completionPanel(){const s=labState;return`<section class="lab-celebration panel"><div class="panel-body"><div class="lab-proof-seal" aria-hidden="true">✧</div><div class="eyebrow">03 / KEEP YOUR DISCOVERY</div><h2>Your recipe checked out!</h2><p class="lab-proof-count">${s.verified.passed}<span> / ${s.verified.total}</span></p><p>Your recipe matches every case in this collection.</p><p class="lab-small">${s.verified.scope} This is a check of your recipe, not a mastery score.</p><form id="lab-teachback"><label for="lab-explanation">Tell Pip why your clue mattered.<span>Your own words, if you’d like. You can skip this.</span></label><textarea id="lab-explanation" name="explanation" maxlength="400" rows="3" placeholder="My clue helped because…">${lEsc(s.explanation)}</textarea><button class="btn secondary" type="submit">Save my words</button><p id="lab-words-status" role="status"></p></form><label class="lab-support-label">For your tutor: was there adult help?<select data-lab-support aria-label="Tutor help in the Rule Lab">${[['unknown','Not recorded / not known'],['independent','No tutor help reported'],['tutor','Tutor helped']].map(([v,text])=>`<option value="${v}" ${(s.support||'unknown')===v?'selected':''}>${text}</option>`).join('')}</select></label><div class="btn-row">${lButton('Download my rule postcard ↓','postcard')}${lButton('Keep exploring my recipe','recipe','',true)}${lButton('Back to my bookshelf','home','',true)}</div><p class="lab-small">The postcard includes your rule, clues, words, help record and checked scope. It stays on this device until you choose to share it.</p></div></section>`;}
function renderLab(keep=false,focusSelector=null){const previousY=window.scrollY,prefs=lRead('fixiverse-access-v1')||{},s=labState;document.title='Fixiverse · The Rule Lab';labRoot.className=`hub storybook-mission rule-lab-screen ${prefs.large?'large':''} ${prefs.motion?'reduced':''}`;labRoot.dataset.labPhase=s.phase;labRoot.dataset.labSubject=s.mission;labRoot.innerHTML=`<header><div class="brand">fixiverse <span class="growth-bookmark">THE RULE LAB</span></div><div class="header-actions">${lButton('My bookshelf','home','',true)}${lButton('Tutor notes','tutor','',true)}${lButton('Read aloud','read','',true)}${lButton('Aa Text size','text',`aria-pressed="${!!prefs.large}"`,true)}</div></header><main id="main" class="rule-lab-shell"><section class="lab-masthead"><div><div class="eyebrow">THE CURIOSITY COLLECTION / A BOOK OF YOUR OWN RULES</div><h1 id="screen-title" tabindex="-1">${s.phase==='experiment'?'Your example.<br>Your own rule.':s.phase==='recipe'?'Build a rule Pip can follow.':'Look what you figured out.'}</h1><p>Build a clue. Challenge an idea. Write a recipe Pip can follow.</p></div><div class="lab-masthead-art" aria-hidden="true"><span>?</span><span>✧</span><span>if…<br>then…</span></div></section><nav class="lab-subjects" aria-label="Rule Lab subject">${[['fraction','Fraction recipes'],['pattern','Pattern recipes']].map(([m,label])=>`<button data-lab="open" data-mission="${m}" aria-pressed="${m===s.mission}">${label}</button>`).join('')}</nav><ol class="lab-chapters" aria-label="Rule Lab progress"><li ${s.phase==='experiment'?'aria-current="step"':''}><b>01</b> Build a clue</li><li ${s.phase==='recipe'?'aria-current="step"':''}><b>02</b> Make a recipe</li><li ${s.phase==='complete'?'aria-current="step"':''}><b>03</b> Keep a discovery</li></ol>${labError?`<p class="result soft" role="status">${lEsc(labError)}</p>`:''}<div class="lab-main-grid"><div>${s.phase==='experiment'?experimentPanel()+ruleCards():s.phase==='recipe'?recipePanel():completionPanel()}</div>${notebook()}</div><p class="growth-local">${window.fixiverseStorage.memoryOnly?'Storage unavailable. Keep this tab open; export a postcard when finished.':'Saved for this learner on this device.'} No timer. No points to lose.</p></main>`;window.fixiverseMissionUI(labRoot,{phase:'lab-'+s.mission+'-'+s.phase,instruction:s.phase==='experiment'?(s.test?(s.test.correct?(s.test.separates?(s.evidence.some(e=>labKey(e.task)===labKey(s.task))?'Your clue is saved. Build another example, or select Build my recipe.':'Select Keep my clue. This example helps tell the remaining rules apart.'):'The rules agree on this example. Change it, or select Help me find a useful test.'):'Compare the pieces or follow the loop. Choose again, then test your prediction.'):s.choice?'Select Test my prediction to compare your answer with the model.':'Use the controls to build an example. Choose your answer, then test it.'):s.phase==='recipe'?(s.verified&&!s.verified.correct?'Your recipe has a case to revisit. Select Investigate this example, or change your instructions and check again.':'Choose the instructions in each row. Run my recipe shows the steps. Check all cases tests the whole collection.'):'Your checked recipe is saved. Add an explanation if you wish, then download your discovery postcard.'});if(keep){window.scrollTo(0,previousY);if(focusSelector){const target=labRoot.querySelector(focusSelector)||labRoot.querySelector('.result');if(target){if(!target.matches('button,select,input,textarea'))target.tabIndex=-1;target.focus({preventScroll:true});}}}else{document.querySelector('#screen-title').focus({preventScroll:true});window.scrollTo(0,0);}}
function labSection(){return`<section class="tutor-section lab-tutor-section"><div class="section-heading"><h2>Rule Lab discoveries</h2><span>Child-built rules, supporting clues and bounded checks</span></div><div class="signal-grid">${['fraction','pattern'].map(m=>{let s=null;try{const raw=lRead(lKey(m));if(raw)s=restoreLab(raw,m);}catch{}return`<article class="signal-card"><span class="mission-number">${m==='fraction'?'01 / FRACTIONS':'02 / PATTERNS'}</span><h3>A recipe of their own</h3><p>${s?`${s.evidence.length} kept clues · ${s.attempts.length} prediction tests · ${s.edits.length} recipe edits · ${s.hints} suggestions.`:'No Rule Lab activity recorded.'}</p><p class="lab-small">${s?.verified?`${s.verified.passed}/${s.verified.total} cases fit the current recipe. ${s.verified.correct?'Checked within the stated finite collection.':'A counterexample remains to investigate.'}`:'A recipe has not been checked yet.'}</p>${s?.explanation?`<blockquote>${lEsc(s.explanation)}</blockquote>`:''}${lButton(s?'Return to this Rule Lab ↗':'Open the Rule Lab ↗','open',`data-mission="${m}"`)}<p class="lab-small">${s?.support==='tutor'?'Tutor help reported.':s?.support==='independent'?'No tutor help reported.':'Tutor help not recorded.'} These actions do not establish mastery.</p></article>`;}).join('')}</div></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-lab]');if(!b)return;const a=b.dataset.lab;labError='';try{if(a==='open'){showLab(b.dataset.mission);return;}if(a==='home'){window.fixiverseHome();return;}if(a==='tutor'){location.hash='tutor';window.fixiverseTutor.show();return;}if(a==='read'){if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(document.querySelector('main').innerText));}else document.querySelector('#announcement').textContent='Read-aloud is not available on this device.';return;}if(a==='text'){const p=lRead('fixiverse-access-v1')||{};p.large=!p.large;window.fixiverseStorage.setItem('fixiverse-access-v1',JSON.stringify(p));renderLab(true,'[data-lab="text"]');document.querySelector('#announcement').textContent=p.large?'Larger text on':'Larger text off';return;}if(a==='experiment'){storeLab(labStep(labState,{type:'case',task:labState.task}));renderLab();return;}if(a==='trace-next'){labTrace=(labTrace+1)%3;renderLab(true,'[data-lab="trace-next"]');document.querySelector('#announcement').textContent=labState.runs.at(-1).trace.steps[labTrace].value;return;}if(a==='postcard'){const alias=window.fixiverseProfiles.list().find(p=>p.id===window.fixiverseProfiles.active()).alias;const html=labCertificate(labState,alias),url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`fixiverse-${labState.mission}-rule-postcard.html`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#announcement').textContent='Your rule postcard was downloaded.';return;}if(a==='run'){traceVisible=true;labTrace=0;}if(['recipe','counterexample'].includes(a))traceVisible=false;storeLab(labStep(labState,{type:a,value:b.dataset.value}));const keep=['choose','test','run','keep'].includes(a)||(a==='verify'&&labState.phase==='recipe');renderLab(keep,`[data-lab="${a==='keep'?'recipe':a}"]${a==='choose'?`[data-value="${b.dataset.value}"]`:''}`);if(a==='verify'&&labState.phase==='recipe'){const result=labRoot.querySelector('.lab-counterexample');if(result){result.tabIndex=-1;result.focus({preventScroll:true});const reduced=labRoot.classList.contains('reduced')||matchMedia('(prefers-reduced-motion: reduce)').matches;result.scrollIntoView({block:'start',behavior:reduced?'instant':'smooth'});}}document.querySelector('#announcement').textContent=a==='keep'?'Clue kept. Your notebook and remaining rules are updated.':a==='verify'?labState.verified.correct?`Your recipe matches all ${labState.verified.total} cases in this collection.`:'A small counterexample can help you improve the recipe.':a==='test'?labState.test.correct?'Your prediction fits. Check whether this case separates the rules.':'Look at the model and try again.':'';}catch(err){labError=err.message;if(labState)renderLab(true);document.querySelector('#announcement').textContent=labError;}});
document.addEventListener('change',e=>{const b=e.target;if(!b.matches('[data-lab-field],[data-lab-recipe],[data-lab-support]'))return;labError='';const focus=b.matches('[data-lab-field]')?`[data-lab-field="${b.dataset.labField}"]`:b.matches('[data-lab-recipe]')?`[data-lab-recipe="${b.dataset.labRecipe}"]`:'[data-lab-support]';try{if(b.matches('[data-lab-recipe]')){traceVisible=false;storeLab(labStep(labState,{type:'edit',slot:b.dataset.labRecipe,value:b.value}));}else if(b.matches('[data-lab-support]'))storeLab(labStep(labState,{type:'support',value:b.value}));else{const t=structuredClone(labState.task),field=b.dataset.labField;if(field.startsWith('part-'))t.pair[+field.at(-1)]=+b.value;else if(field==='length')t.length=+b.value;else if(field==='loop-size'){if(+b.value===2)t.block=t.block.slice(0,2);else if(t.block.length===2)t.block.push(LAB_TOKENS.find(x=>!t.block.includes(x)));}else t.block[+field.at(-1)]=b.value;storeLab(labStep(labState,{type:'case',task:t}));}renderLab(true,focus);}catch(err){labError=err.message;renderLab(true,focus);document.querySelector('#announcement').textContent=labError;}});
document.addEventListener('submit',e=>{if(e.target.id!=='lab-teachback')return;e.preventDefault();try{storeLab(labStep(labState,{type:'explain',value:new FormData(e.target).get('explanation')}));document.querySelector('#lab-words-status').textContent='Your words are saved in your postcard.';}catch(err){document.querySelector('#lab-words-status').textContent=err.message;}});
window.fixiverseLab={show:showLab,section:labSection};
